class Solution {
    public List<Integer> largestDivisibleSubset(int[] nums) {
        Arrays.sort(nums);
        List<Integer> best = new ArrayList<>();
        backtrack(nums, 0, new ArrayList<>(), best);
        return best;
    }
    private void backtrack(int[] nums, int idx, List<Integer> cur, List<Integer> best) {
        if (cur.size() > best.size()) {
            best.clear();
            best.addAll(cur);
        }
        for (int i = idx; i < nums.length; i++) {
            if (cur.isEmpty() || nums[i] % cur.get(cur.size() - 1) == 0) {
                cur.add(nums[i]);
                backtrack(nums, i + 1, cur, best);
                cur.remove(cur.size() - 1);
            }
        }
    }
}

