class Solution {
    public int numRollsToTarget(int n, int k, int target) {
        int[][] memo = new int[n + 1][target + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(n, k, target, memo);
    }
    private int dfs(int d, int k, int t, int[][] memo) {
        if (d == 0) return t == 0 ? 1 : 0;
        if (t < 0) return 0;
        if (memo[d][t] != -1) return memo[d][t];
        long ways = 0;
        for (int f = 1; f <= k; f++) {
            ways = (ways + dfs(d - 1, k, t - f, memo)) % 1_000_000_007;
        }
        return memo[d][t] = (int) ways;
    }
}

