    private int dfs(String[] s, int idx, int m, int n, int[][][] memo) {
        if (idx == s.length) return 0;
        if (memo[idx][m][n] != 0) return memo[idx][m][n];
        int skip = dfs(s, idx + 1, m, n, memo);
        int take = 0;
        int zeros = 0, ones = 0;
        for (char c : s[idx].toCharArray()) {
            if (c == '0') zeros++; else ones++;
        }
        if (m >= zeros && n >= ones) {
            take = 1 + dfs(s, idx + 1, m - zeros, n - ones, memo);
        }
        return memo[idx][m][n] = Math.max(skip, take);
    }
}

