    public int maxSumAfterPartitioning(int[] arr, int k) {
        int[] memo = new int[arr.length];
        return dfs(arr, 0, k, memo);
    }
    private int dfs(int[] arr, int idx, int k, int[] memo) {
        if (idx == arr.length) return 0;
        if (memo[idx] != 0) return memo[idx];
        int maxVal = 0, best = 0;
        for (int len = 1; len <= k && idx + len <= arr.length; len++) {
            maxVal = Math.max(maxVal, arr[idx + len - 1]);
            best = Math.max(best, maxVal * len + dfs(arr, idx + len, k, memo));
        }
        return memo[idx] = best;
    }
}

