        if total % 3 == 0:
            return total
        rem = float('inf')
        if total % 3 == 1:
            if r1:
                rem = min(rem, r1[0])
            if len(r2) >= 2:
                rem = min(rem, r2[0] + r2[1])
        else:
            if r2:
                rem = min(rem, r2[0])
