        int n = startTime.length;
        int[][] jobs = new int[n][3];
        for (int i = 0; i < n; i++) {
            jobs[i] = new int[]{startTime[i], endTime[i], profit[i]};
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a[1], b[1]));
        int[] dp = new int[n + 1];
        for (int i = 0; i < n; i++) {
            int low = 0, high = i - 1;
            int lastCompatible = -1;
            while (low <= high) {
                int mid = (low + high) >>> 1;
                if (jobs[mid][1] <= jobs[i][0]) {
                    lastCompatible = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            int take = jobs[i][2] + (lastCompatible != -1 ? dp[lastCompatible + 1] : 0);
            dp[i + 1] = Math.max(dp[i], take);
        }
        return dp[n];
    }
}

