        n = len(jobs)
        dp = [0] * (n + 1)
        for i in range(n):
            end, start, p = jobs[i]
            low, high = 0, i - 1
            last = -1
            while low <= high:
                mid = (low + high) // 2
                if jobs[mid][0] <= start:
                    last = mid
                    low = mid + 1
                else:
                    high = mid - 1
            dp[i + 1] = max(dp[i], p + (dp[last + 1] if last != -1 else 0))
        return dp[n]

