class Solution {
    private static final int MOD = 1_000_000_007;
    public int numDecodings(String s) {
        return (int) dfs(s, 0);
    }
    private long dfs(String s, int idx) {
        if (idx == s.length()) return 1;
        if (s.charAt(idx) == '0') return 0;
        long ways = (s.charAt(idx) == '*' ? 9 : 1) * dfs(s, idx + 1) % MOD;
        if (idx + 1 < s.length()) {
            char c1 = s.charAt(idx), c2 = s.charAt(idx + 1);
            ways = (ways + ways2(c1, c2) * dfs(s, idx + 2)) % MOD;
        }
        return ways;
    }
    private int ways2(char c1, char c2) {
        if (c1 == '*' && c2 == '*') return 15;
        if (c1 == '*') return (c2 <= '6') ? 2 : 1;
        if (c2 == '*') {
            if (c1 == '1') return 9;
            if (c1 == '2') return 6;
            return 0;
        }
        int val = (c1 - '0') * 10 + (c2 - '0');
        return (val >= 10 && val <= 26) ? 1 : 0;
    }
}

